/* The patro queries of PATRO section 2 over the dense per-day tables of PATRO section 3. The
 * tables are generated by tools/codegen and exist only in this translation unit. */
#include "nepdate_patro.h"

#include <nepdate.h>

#include "generated/calendar_tables.h"
#include "generated/patro_tables.h"

#include <stddef.h>
#include <stdint.h>

_Static_assert(NEPDATE_PATRO_CALENDAR_FINGERPRINT == NEPDATE_CAL_FINGERPRINT,
               "patro tables and the calendar were built from different data");
_Static_assert(sizeof(nepdate_patro_day_tithi) == NEPDATE_PATRO_DAYS, "generated day table size");
_Static_assert(sizeof(nepdate_patro_holiday_values) ==
                   NEPDATE_PATRO_HOLIDAYS * sizeof(nepdate_patro_holiday_values[0]),
               "generated holiday table size");

/* The covered day's serial, or false for a value no function of the core made. */
static bool patro_serial(nepdate_date date, uint32_t *serial) {
    const uint32_t value = (uint32_t)date.value - 1U;
    if (value >= (uint32_t)NEPDATE_CAL_DAYS) {
        return false;
    }
    *serial = value;
    return true;
}

/* Name index to its np and en bytes in the blob. Precondition: index is in the table. */
static nepdate_patro_name name_at(uint16_t index) {
    nepdate_patro_name name;
    const uint32_t start = nepdate_patro_name_offsets[(size_t)index * 2U];
    const uint32_t middle = nepdate_patro_name_offsets[(size_t)index * 2U + 1U];
    const uint32_t end = nepdate_patro_name_offsets[(size_t)index * 2U + 2U];
    name.np = nepdate_patro_name_blob + start;
    name.np_length = (size_t)(middle - start);
    name.en = nepdate_patro_name_blob + middle;
    name.en_length = (size_t)(end - middle);
    return name;
}

static nepdate_patro_day_info empty_info(void) {
    nepdate_patro_day_info info;
    info.has_tithi = false;
    info.tithi.np = NULL;
    info.tithi.np_length = 0;
    info.tithi.en = NULL;
    info.tithi.en_length = 0;
    info.is_public_holiday = false;
    info.event_count = 0;
    return info;
}

nepdate_status nepdate_patro_info(nepdate_date date, nepdate_patro_day_info *out) {
    if (out == NULL) {
        return NEPDATE_E_NULL;
    }
    uint32_t serial = 0;
    if (!patro_serial(date, &serial)) {
        return NEPDATE_E_INVALID_DATE;
    }
    nepdate_patro_day_info info = empty_info();
    if (serial < (uint32_t)NEPDATE_PATRO_FIRST_SERIAL ||
        serial - (uint32_t)NEPDATE_PATRO_FIRST_SERIAL >= (uint32_t)NEPDATE_PATRO_DAYS) {
        *out = info;
        return NEPDATE_OK;
    }
    const uint32_t offset = serial - (uint32_t)NEPDATE_PATRO_FIRST_SERIAL;
    const uint8_t tithi = nepdate_patro_day_tithi[offset];
    if (tithi != 0xFFU) {
        info.has_tithi = true;
        info.tithi = name_at(tithi);
    }
    info.is_public_holiday =
        ((nepdate_patro_holiday_bits[offset / 64U] >> (offset % 64U)) & UINT64_C(1)) != 0;
    info.event_count = (size_t)nepdate_patro_day_event_start[offset + 1U] -
                       (size_t)nepdate_patro_day_event_start[offset];
    *out = info;
    return NEPDATE_OK;
}

nepdate_range nepdate_patro_coverage(void) {
    const nepdate_range range = {{(int32_t)(NEPDATE_PATRO_FIRST_SERIAL + 1U)},
                                 {(int32_t)(NEPDATE_PATRO_FIRST_SERIAL + NEPDATE_PATRO_DAYS)}};
    return range;
}

size_t nepdate_patro_public_holidays(nepdate_date *dates, size_t capacity) {
    if (dates == NULL || capacity == 0) {
        return NEPDATE_PATRO_HOLIDAYS;
    }
    const size_t count =
        capacity < (size_t)NEPDATE_PATRO_HOLIDAYS ? capacity : (size_t)NEPDATE_PATRO_HOLIDAYS;
    for (size_t i = 0; i < count; i++) {
        dates[i].value = nepdate_patro_holiday_values[i];
    }
    return NEPDATE_PATRO_HOLIDAYS;
}

size_t nepdate_patro_events(nepdate_date date, nepdate_patro_name *events, size_t capacity) {
    uint32_t serial = 0;
    if (!patro_serial(date, &serial)) {
        return 0;
    }
    if (serial < (uint32_t)NEPDATE_PATRO_FIRST_SERIAL ||
        serial - (uint32_t)NEPDATE_PATRO_FIRST_SERIAL >= (uint32_t)NEPDATE_PATRO_DAYS) {
        return 0;
    }
    const uint32_t offset = serial - (uint32_t)NEPDATE_PATRO_FIRST_SERIAL;
    const uint16_t first = nepdate_patro_day_event_start[offset];
    const size_t count = (size_t)nepdate_patro_day_event_start[offset + 1U] - (size_t)first;
    if (events == NULL || capacity == 0) {
        return count;
    }
    const size_t written = capacity < count ? capacity : count;
    for (size_t i = 0; i < written; i++) {
        events[i] = name_at(nepdate_patro_event_names[first + i]);
    }
    return count;
}
